#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    // Operation: split into [0..x-1], [x..n-y-1], [n-y..n-1]
    // Result: [n-y..n-1] + [x..n-y-1] + [0..x-1]
    auto apply = [&](int x, int y) {
        vector<int> np;
        for(int i = n-y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n-y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x, y});
    };

    for(int target = 0; target < n - 1; target++){
        // Find where target+1 is
        int pos = -1;
        for(int i = target; i < n; i++){
            if(p[i] == target + 1){ pos = i; break; }
        }
        if(pos == target) continue;

        // Step 1: Move element at pos to position n-1
        if(pos != n - 1){
            // We want p[pos] to end up at position n-1
            // p[pos] is in the "first" part if we set x = pos+1
            // After apply(x, y): first x elements go to end. p[pos] = p[x-1] goes to position n-1
            // We need x = pos+1, and y such that x+y < n, y >= 1
            // y = 1 works as long as pos+1+1 < n, i.e., pos < n-2
            // If pos == n-2: x = n-1, y >= 1, x+y >= n. Problem.
            // For pos == n-2: use x=1, y=1 first to rotate, then find again

            if(pos == n - 2){
                // apply(1,1): [p[n-1], p[1..n-2], p[0]]
                // element was at n-2, now at n-2 still (it's in middle part)
                // Actually middle is [1..n-2], element at n-2 maps to index 1+(n-2-1)=n-2. Hmm same.
                // Use x = pos+1 = n-1, need y but x+y<n means y<1. Can't.
                // Alternative: set y = n - pos = 2, x = 1 (need x+y < n, 3 < n, ok if n>3)
                if(n > 3){
                    // y=2: suffix is [p[n-2], p[n-1]], they go to front
                    // x=1: [p[0]] goes to end
                    // Result: [p[n-2], p[n-1], p[1..n-3], p[0]]
                    // Element was at n-2, now at position 0
                    apply(1, 2);
                    pos = 0;
                    // Now use x=pos+1=1, y=1
                    apply(1, 1);
                    // p[0] goes to end → position n-1
                    pos = n-1;
                } else {
                    // n==3, pos=1, target must be 0
                    apply(1, 1);
                    for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
                    if(pos==n-1) goto step2;
                    apply(pos+1, 1);
                    pos = n-1;
                }
            } else {
                apply(pos + 1, 1);
                pos = n - 1;
            }
        }
        step2:
        if(pos == n-1 && target < n-1){
            // Move from n-1 to target
            // y = n - target: suffix includes positions [target..n-1], element at n-1 goes to position n-1-target in the suffix → after apply, position n-1-target
            // Actually: set y = n - 1 - target, x = max(1, target)
            int y = n - 1 - target;
            int x = target > 0 ? target : 1;
            if(x + y < n && x > 0 && y > 0){
                apply(x, y);
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n", x, y);
}
